def _generated_rows(pool: list[str], stage_counts: list[int]) -> list[list[str]]:
    """Fill each educational stage with real registered items from its mod."""
    return [[pool[(stage * 3 + index) % len(pool)] for index in range(count)] for stage, count in enumerate(stage_counts)]


def _target_stage_counts(namespace: str) -> list[int]:
    config = CHAPTERS[namespace]
    append_control = config.get("append_control", True)
    counts = [len(stage[2]) + (1 if append_control else 0) for stage in config["stages"]]
    extra = config.get("target_count", sum(counts)) - sum(counts)
    for index in range(extra):
        counts[index % len(counts)] += 1
    return counts


